void CZBodyPart::Orient()
{
	if (this != NULL)
	{
		m_node->SetPosition(m_pos.x, m_pos.y, m_pos.z);
	}

	if (&m_rot != NULL)
	{
		m_node->SetRotation(&m_rot);
	}
}

